import { lazy, Suspense, useCallback, useEffect, useRef, useState } from 'react';
import { LazyMotion, MotionConfig, domAnimation } from 'motion/react';
import type { LineId } from './data/types';
import { Nav } from './components/Nav';
import { Footer } from './components/Footer';
import { Hero } from './components/Hero';
import { Register } from './components/Register';
import { rowByAnchor, site } from './lib/site';

const Receipt = lazy(() => import('./components/Receipt'));
const DEFAULT_LINE = site.lines[0]!.id;

const fromHash = () => {
  const h = decodeURIComponent(window.location.hash.slice(1));
  return rowByAnchor.has(h) ? h : null;
};

export default function App() {
  const [anchor, setAnchor] = useState<string | null>(fromHash);
  const [line, setLine] = useState<LineId>(DEFAULT_LINE);
  const [everOpened, setEverOpened] = useState(Boolean(anchor));
  const trigger = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const sync = () => {
      const h = fromHash();
      setAnchor(h);
      if (h) setEverOpened(true);
    };
    window.addEventListener('hashchange', sync);
    window.addEventListener('popstate', sync);
    return () => {
      window.removeEventListener('hashchange', sync);
      window.removeEventListener('popstate', sync);
    };
  }, []);

  const open = useCallback((a: string, l: LineId, el: HTMLElement | null) => {
    trigger.current = el;
    setLine(l);
    setAnchor(a);
    setEverOpened(true);
    history.pushState(null, '', `#${a}`);
  }, []);

  const close = useCallback(() => {
    setAnchor(null);
    if (window.location.hash) history.pushState(null, '', window.location.pathname + window.location.search);
  }, []);

  const returnFocus = useCallback(() => {
    const el = trigger.current;
    if (el && document.contains(el)) el.focus();
    else document.getElementById('register')?.querySelector<HTMLElement>('button[tabindex="0"]')?.focus();
  }, []);

  return (
    <MotionConfig reducedMotion="user">
      <LazyMotion features={domAnimation} strict>
        <a
          href="#main"
          className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-3 focus:z-50 focus:bg-surface focus:px-3 focus:py-2"
        >
          Skip to the record
        </a>
        <Nav />
        <main id="main" className="mx-auto max-w-[84rem] px-5 md:px-10">
          <Hero />
          <Register onOpen={open} />
        </main>
        <Footer generatedAt={site.generated_at} />
        {everOpened && (
          <Suspense fallback={null}>
            <Receipt
              row={anchor ? rowByAnchor.get(anchor) ?? null : null}
              line={line}
              onLine={setLine}
              onClose={close}
              returnFocus={returnFocus}
            />
          </Suspense>
        )}
      </LazyMotion>
    </MotionConfig>
  );
}
import { site, longDate, prNum } from '@/lib/site';

export function Hero() {
  const s = site.summary;
  const v = s.verdicts;
  const read = site.links.prs.find((u) => u.endsWith('/pull/13')) ?? site.links.prs[0];
  const q = site.query;
  return (
    <section id="top" aria-labelledby="headline" className="grid gap-y-8 pb-16 pt-14 md:grid-cols-12 md:pt-24">
      <h1
        id="headline"
        className="text-[2.35rem] leading-[1.06] tracking-[-0.02em] sm:text-5xl md:col-span-11 lg:text-[4.1rem] xl:col-span-10"
      >
        Django stopped patching 4.2 on {longDate(site.eol)}. Debian 13 and Ubuntu 24.04 still ship it.
      </h1>
      <p className="max-w-[38ch] text-xl leading-snug text-ink md:col-span-8 md:text-2xl">
        Heirloom is an agent that keeps end-of-life software patched — and proves which old versions are actually
        vulnerable.
      </p>
      <div className="max-w-measure md:col-span-8">
        <p className="text-[1.0625rem] leading-relaxed">
          Django published {s.cves} security advisories for its supported versions after 4.2&rsquo;s end of life.
          Heirloom wrote an independent probe for each, calibrated it on Django&rsquo;s own fix, and ran it on the 4.2
          lines people still run. <strong className="font-medium">{s.prs} are fix ready</strong>: candidate backport
          pull requests whose probe fails ×{s.probe_before} before the fix and passes ×{s.probe_after} after it.{' '}
          <strong className="font-medium">{v.NOT_AFFECTED_PROVEN ?? 0} is proven not affected.</strong>{' '}
          <strong className="font-medium">{v.UNPROVEN ?? 0} are unproven</strong>, and for each it filed the evidence
          instead of guessing. It asked {s.questions === 1 ? 'one question' : `${s.questions} questions`} (
          <a className="link" href={q.issue}>
            {prNum(q.issue)}
          </a>
          ); the answer became precedent {q.precedent.id}, which a later backport reused without asking.
        </p>
        <p className="mt-6 font-mono text-xs leading-relaxed tracking-wide text-muted">
          Record {site.record} · {s.cves} advisories · {site.lines.length} release lines · data generated{' '}
          <time dateTime={site.generated_at}>{site.generated_at}</time> · built during neatHack, Oct 10–12 2026
        </p>
        <div className="mt-6 flex flex-wrap gap-x-8 gap-y-2">
          <a href="#register" className="press inline-flex min-h-11 items-center text-lg underline decoration-ink/40 underline-offset-[0.2em] hover-underline">
            Open the register
          </a>
          {read && (
            <a href={read} className="press inline-flex min-h-11 items-center text-lg underline decoration-ink/40 underline-offset-[0.2em] hover-underline">
              Read a backport ({prNum(read)})
            </a>
          )}
        </div>
      </div>
    </section>
  );
}
export const SECTIONS = [
  ['register', 'Register'],
  ['finding', 'Finding'],
  ['method', 'Method'],
  ['query', 'Query'],
  ['results', 'Results'],
  ['verify', 'Verify'],
] as const;
import data from '@/data/site.json';
import type { Chip, Line, LineId, Row, Site } from '@/data/types';

export const site = data as unknown as Site;
export const lineById = Object.fromEntries(site.lines.map((l) => [l.id, l])) as Record<LineId, Line>;
export const rowByAnchor = new Map<string, Row>(site.rows.map((r) => [r.anchor, r]));

export const CHIP_META: Record<Chip, { word: string; symbol: string; cls: string; meaning: string }> = {
  FIX_READY: { word: 'Fix ready', symbol: '✓', cls: 'bg-fix-bg text-fix-fg border-fix-fg/25', meaning: 'affected, and a verified candidate backport is open' },
  NOT_AFFECTED: { word: 'Not affected', symbol: '○', cls: 'bg-na-bg text-na-fg border-na-fg/25', meaning: 'proven not affected by a calibrated probe' },
  UNPROVEN: { word: 'Unproven', symbol: '?', cls: 'bg-unp-bg text-unp-fg border-unp-fg/25', meaning: 'the probe could not decide; evidence filed' },
  AFFECTED: { word: 'Affected', symbol: '!', cls: 'bg-aff-bg text-aff-fg border-aff-fg/25', meaning: 'the calibrated probe fails on this line' },
  NO_PROBE: { word: 'No probe', symbol: '–', cls: 'bg-np-bg text-np-fg border-np-fg/25', meaning: 'no probe passed calibration' },
};

export const REASONS: Record<string, string> = {
  NO_REACH: 'the probe never reached the code the fix changes on this line',
  NON_DISCRIMINATING: 'no probe failed before the fix and passed after it',
  PROBE_ERROR: 'the probe could not be made to run cleanly',
  MUTANT_UNBUILDABLE: 'the vulnerability could not be rebuilt inside this line to check the probe catches it',
  MUTANT_SURVIVED: 'a rebuilt vulnerability was not caught by the probe',
  FLAKY: 'the probe gave different results across runs',
  FAIL_MISMATCH: 'the probe failed on this line with different test ids than before the fix',
  STRUCTURAL_TEST: 'upstream tests error before the fix, so they cannot serve as the probe',
  ENV_SKIP: 'the probe needs a backend this harness does not run',
  ALREADY_PUBLISHED: 'published earlier by the first end-to-end run; no new PR',
};

export const GATES: Record<string, string> = {
  C0: 'Upstream tests fail before the fix and pass after it',
  C1: 'Probe fails on U⁻ with stable test ids, passes on U⁺',
  C2: 'Probe runs cleanly on this line',
  C3: 'Coverage reaches the code the fix changes',
  C4ab: 'A rebuilt vulnerability on this line is caught',
  C4c: 'The vulnerable lines were never on this line (provenance)',
  absent: 'The fixed symbol does not exist on this line',
};

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** 2026-08-04 → "Aug 4 2026" */
export function shortDate(iso: string) {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return `${MONTHS[(m ?? 1) - 1]} ${d} ${y}`;
}
/** 2026-04-07 → "7 April 2026" */
export function longDate(iso: string) {
  const full = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return `${d} ${full[(m ?? 1) - 1]} ${y}`;
}
export const prNum = (url: string) => `#${url.split('/').pop()}`;
// generated by scripts/build-data.mjs — do not edit
export type Chip = 'FIX_READY' | 'NOT_AFFECTED' | 'UNPROVEN' | 'AFFECTED' | 'NO_PROBE';
export type MatrixVerdict = 'AFFECTED' | 'NOT_AFFECTED_PROVEN' | 'UNPROVEN' | 'no_calibrated_probe';
export type LineId = '4.2.30' | 'debian-trixie' | 'ubuntu-noble';

export interface Line {
  id: LineId;
  name: string;
  note: string;
  kind: string;
  version: string;
  upstream: string;
  label: string;
  tip: string;
  changelog_date?: string;
}

export interface Cell {
  line: LineId;
  verdict: MatrixVerdict;
  chip: Chip;
}

export interface Treatment {
  verdict: string;
  reason?: string;
  status: string;
  treatment: 'pr' | 'issue';
  link: string;
  number: number;
  run_id?: string;
  checkpoint?: string;
  traces?: string[];
  cost_usd: number;
  minutes: number;
  escalated: boolean;
  depends_on?: string[];
  stacked_on?: string;
  note?: string;
  fail_to_pass?: { before: string[]; after: string[] };
  precedent?: string;
  asked?: string;
  waited_on?: string;
  logs?: string;
  followups?: { date: string; kind: string }[];
}

export interface Row {
  acc: string;
  anchor: string;
  cve: string;
  title: string;
  date: string;
  url?: string;
  cells: Cell[];
  affected: number;
  campaign: Treatment;
}

export interface Stop {
  date: string;
  kind: 'eol' | 'advisories' | 'distro' | 'followup';
  label: string;
}

export interface Site {
  record: string;
  generated_at: string;
  eol: string;
  campaign: string;
  lines: Line[];
  chips: Chip[];
  summary: {
    cves: number;
    verdicts: Record<string, number>;
    prs: number;
    issues: number;
    questions: number;
    fail_to_pass: number;
    probe_before: number;
    probe_after: number;
    chip_counts: Record<Chip, number>;
    by_line: Record<LineId, Record<MatrixVerdict, number>>;
    cost_usd: number;
    minutes: number;
  };
  rows: Row[];
  stops: Stop[];
  connector?: { from: string; to: string; pr: number; on: number; date: string };
  query_marker: { cve: string; number: number };
  query: {
    issue: string;
    number: number;
    asked_by: string;
    asked_at: string;
    asking_trace?: string;
    waited: string[];
    precedent: {
      id: string;
      kind: string;
      answer: string;
      stored_at: string;
      applied_by: { cve: string; pr: string; number: number; trace_id: string; run_id: string }[];
    };
  };
  backtest: Record<'v1' | 'v2', {
    cases: number;
    decided: number;
    accuracy: number;
    false_not_affected: number;
    false_affected: number;
    unproven: number;
    escalation_rate: number;
    usd_per_case: number;
  }>;
  detections: { name: string; hits: number }[];
  economics: { inputs: { name: string; base: string; bear: string; bull: string; status: string }[]; pages: { name: string; url: string }[] };
  links: { prs: string[]; issues: string[] };
}

export interface Gate {
  id: string;
  ok: boolean;
  detail?: string;
  reason?: string;
}

export interface RunSummary {
  outcomes: string[];
  failing_ids: string[];
}

export interface ReceiptCell {
  line: LineId;
  verdict: MatrixVerdict;
  reason?: string;
  detail?: string;
  gates: Gate[];
  probe?: { origin: 'porter' | 'hand-written'; sha: string };
  fix?: { series: string; commits: string[]; um: string };
  runs: Partial<Record<'um' | 'up' | 'lt', RunSummary>>;
}

export interface Receipt {
  cve: string;
  cells: ReceiptCell[];
  matrix_logs?: string;
}
